<script setup lang="ts">
import PmsTableControls from './PmsTableControls.vue';
import {ref,onMounted,onUnmounted,computed} from 'vue';import {pmsApi} from './api';const exportMenu=ref<HTMLDetailsElement|null>(null);function closeExport(){if(exportMenu.value)exportMenu.value.open=false;}function outsideExport(event:PointerEvent){if(exportMenu.value?.open&&!exportMenu.value.contains(event.target as Node))closeExport();}function escapeExport(event:KeyboardEvent){if(event.key==='Escape'&&exportMenu.value?.open){closeExport();exportMenu.value.querySelector<HTMLElement>('summary')?.focus();}}onMounted(()=>{document.addEventListener('pointerdown',outsideExport,true);document.addEventListener('keydown',escapeExport);});onUnmounted(()=>{document.removeEventListener('pointerdown',outsideExport,true);document.removeEventListener('keydown',escapeExport);});const tablePage=ref(1),tableSize=ref(10),search=ref('');const shown=computed(()=>rows.value.filter(row=>Object.values(row).filter(v=>typeof v==='string').join(' ').toLowerCase().includes(search.value.toLowerCase())));const paged=computed(()=>tableSize.value<0?shown.value:shown.value.slice((tablePage.value-1)*tableSize.value,tablePage.value*tableSize.value));const data=ref<any>(null),rows=ref<any[]>([]),busy=ref(false),error=ref(''),filters=ref({user_id:'',project_id:'',start_date:'',end_date:''});function exportUrl(format:string){return '/pms/api/work-logs/export/'+format+'?'+new URLSearchParams(filters.value);}
async function copyLogs(){try{await navigator.clipboard.writeText([Object.values(columns).join('\t'),...rows.value.map(r=>Object.keys(columns).map(k=>r[k]??'').join('\t'))].join('\n'));}catch(e){error.value=(e as Error).message;}}
async function load(){busy.value=true;try{const d=await pmsApi('work-logs?'+new URLSearchParams(filters.value),'','GET',undefined,true);rows.value=d.data;error.value='';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}onMounted(async()=>{try{data.value=(await pmsApi('work-logs')).data;await load();}catch(e){error.value=(e as Error).message;}});const columns:any={project:'Project',type:'Type',title:'Title',status:'Status',user:'User',time_spent:'Invested Time',created_at:'Start Date',due_date:'Due Date',assigned_by:'Assigned by'};
</script><template><section class="pms-work-logs"><div class="admin-section-heading"><div><h4 class="mb-1">Work Logs</h4><p class="text-muted">Review completed work and tracked time by employee, project and date.</p></div><span class="badge bg-label-primary"><i class="ti ti-clock me-1" aria-hidden="true"></i>Time and activity report</span></div><p v-if="error" class="notice admin-error">{{error}}</p><form class="pms-work-log-filters" @submit.prevent="load"><div class="pms-work-log-filter-grid"><label>User<select class="form-select" v-model="filters.user_id"><option value="">All</option><option v-for="u in data?.users" :key="u.id" :value="u.id">{{u.name}}</option></select></label><label>Project<select class="form-select" v-model="filters.project_id"><option value="">All</option><option v-for="p in data?.projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>From<input class="form-control" type="date" v-model="filters.start_date"></label><label>To<input class="form-control" type="date" v-model="filters.end_date" :min="filters.start_date"></label><div class="pms-filter-actions"><button type="button" class="button pms-work-log-reset" @click="filters={user_id:'',project_id:'',start_date:'',end_date:''};load()">Reset</button><button class="button primary" :disabled="busy">Apply Filter</button></div></div></form><template v-if="busy" role="status"></template><div class="pms-table-card"><PmsTableControls :total="shown.length" v-model:page="tablePage" v-model:size="tableSize" v-model:search="search"/><div class="pms-work-log-export-row"><details ref="exportMenu" class="pms-export-menu"><summary class="button primary"><i class="ti ti-upload" aria-hidden="true"></i>Export</summary><div @click="closeExport"><button @click="copyLogs">Copy</button><a v-for="f in ['csv','xlsx','pdf']" :key="f" :href="exportUrl(f)">{{f.toUpperCase()}}</a></div></details></div><table class="pms-table"><thead><tr><th v-for="(label,key) in columns" :key="key" scope="col">{{label}}</th></tr></thead><tbody><tr v-for="(row,index) in paged" :key="index"><td v-for="(_,key) in columns" :key="key">{{row[key]}}</td></tr><tr v-if="!rows.length"><td colspan="9">No work logs match these filters.</td></tr></tbody></table><PmsTableControls footer :total="shown.length" v-model:page="tablePage" v-model:size="tableSize"/></div></section></template>